import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function CartPage({ cart, onClearCart }) {
    const navigate = useNavigate();
    const [orderPlaced, setOrderPlaced] = useState(false);

    const handlePlaceOrder = async () => {
        const token = localStorage.getItem('token');
        const orderData = {
            products: cart.map((item) => ({
                product: item.id,
                quantity: item.quantity,
                price: item.price,
            })),
            totalAmount: cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
        };

        try {
            const API_URL = 'http://localhost:5000';

            const response = await fetch(`${API_URL}/api/orders`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify(orderData),
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Failed to place order.');
            }

            const placedOrder = await response.json();
            console.log('Order placed:', placedOrder);

            // Show success message
            setOrderPlaced(true);

            // Clear the cart
            console.log('Calling onClearCart...');
            onClearCart(); // Clear the cart
            console.log('Cart cleared successfully.');

            // Redirect to home page after 3 seconds
            setTimeout(() => {
                navigate('/');
            }, 3000);
        } catch (err) {
            console.error('Error placing order:', err.message);
            alert(err.message);
        }
    };

    return (
        <div>
            <h1>Your Cart</h1>
            {orderPlaced ? (
                <div>
                    <h2 style={{ color: 'green' }}>Order placed successfully!</h2>
                    <p>You will be redirected to the home page shortly...</p>
                </div>
            ) : cart.length === 0 ? (
                <p>Your cart is empty.</p>
            ) : (
                <>
                    <ul>
                        {cart.map((item) => (
                            <li key={item.id}>
                                {item.name} - ${item.price} (x{item.quantity})
                            </li>
                        ))}
                    </ul>
                    <h2>Total: ${cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2)}</h2>
                    <button onClick={handlePlaceOrder}>Place Order</button>
                </>
            )}
        </div>
    );
}

export default CartPage;
